func (c *CookieMan) Set(w http.ResponseWriter, name string, value []byte, opt *CookieOption) error {
	v, err := c.cipher.Encrypt(value)
	if err != nil {
		return err
	}
	http.SetCookie(w, c.cookie(name, base64.URLEncoding.EncodeToString(v), opt))
	return nil
}

